"""t69 — 4.13.0: 🧪 Gasometria 360X (300 flashcards, 100 questões, 235 casos guiados, analisador) + Jornada expandida.
Uso: python3 t69_gaso.py [URL]"""
import sys
from playwright.sync_api import sync_playwright
URL = sys.argv[1] if len(sys.argv) > 1 else "http://localhost:8765/index.html"; ok = []; bad = []
def chk(c, m): (ok if c else bad).append(m); print(("✅ " if c else "❌ ") + m)
ROOT = "🧪 Gasometria 360X"
OLD = ["st3", "st365", "sim50_1", "sim100_20", "xp500", "xp100000", "rk1", "rk6", "qa10", "qa600", "acc70", "acc90", "qc10", "mc10", "mn10", "ho10", "hb5", "hn1", "hu5", "cd100", "cd10000", "mt1", "wkrec"]
with sync_playwright() as p:
    br = p.chromium.launch(executable_path="/usr/bin/google-chrome", args=["--no-sandbox"])
    for vp, lab in [({"width": 390, "height": 844}, "celular"), ({"width": 1366, "height": 900}, "desktop")]:
        ctx = br.new_context(viewport=vp); pg = ctx.new_page(); errs = []
        pg.on("pageerror", lambda e: errs.append(str(e)))
        pg.goto(URL + "#inicio"); pg.wait_for_function("S && S.cards && S.cards.length>1000", timeout=90000)
        T = f"[{lab}]"
        chk(pg.evaluate("APP_VERSION") == "4.13.0", f"{T} versão 4.13.0")
        # ---------- flashcards ----------
        n = pg.evaluate(f"S.official.filter(c=>c.deck.startsWith({ROOT!r})).length"); chk(n == 300, f"{T} 300 flashcards de gasometria ({n})")
        nd = pg.evaluate(f"new Set(S.official.filter(c=>c.deck.startsWith({ROOT!r})).map(c=>c.deck)).size"); chk(nd == 10, f"{T} 10 baralhos ({nd})")
        ni = pg.evaluate(f"new Set(S.official.filter(c=>c.deck.startsWith({ROOT!r})).map(c=>c.id)).size"); chk(ni == 300, f"{T} ids únicos ({ni})")
        act = pg.evaluate(f"S.cards.filter(c=>c.deck.startsWith({ROOT!r})&&c.col==='gaso').length"); chk(act == 300, f"{T} coleção 'gaso' ativa por padrão ({act})")
        r = pg.evaluate(f"""(()=>{{const cs=S.official.filter(c=>c.deck.startsWith({ROOT!r}));let fr=0,nodx=0,tab=0,back=0;
           for(const c of cs){{const q=c.q.split('<hr id=answer>')[0]; if(/🧪 <b>Gaso #\\d{{3}}/.test(q)) fr++; if(!/✅/.test(q)) nodx++; if(/<table/.test(q)) tab++; if(/🔎/.test(c.a)&&/✅/.test(c.a)) back++;}}
           return [fr,nodx,tab,back]}})()""")
        chk(r[0] == 300, f"{T} frente numerada 'Gaso #NNN' ({r[0]})")
        chk(r[1] == 300, f"{T} frente não revela o diagnóstico ({r[1]})")
        chk(r[2] >= 235, f"{T} laudo em tabela na frente dos casos ({r[2]})")
        chk(r[3] == 300, f"{T} verso com ✅ resposta + 🔎 explicação ({r[3]})")
        pg.evaluate("location.hash='#estudar'"); pg.wait_for_timeout(500)
        pg.evaluate(f"(async()=>{{const c=S.official.find(c=>c.deck.startsWith({ROOT!r})&&/<table/.test(c.q)); $('#studyEmpty').style.display='none'; $('#cardHost').style.display='block'; await renderInto($('#cardHost'), c.a, 'codice', c.deck)}})()")
        pg.wait_for_timeout(700)
        tw = pg.evaluate("(()=>{const r=$('#cardHost').shadowRoot,t=r.querySelector('table'),c=r.querySelector('.card');return [t?t.getBoundingClientRect().width:-1,c.getBoundingClientRect().width]})()")
        chk(0 < tw[0] <= tw[1] + 1, f"{T} tabela do laudo cabe no card ({tw[0]:.0f}/{tw[1]:.0f}px)")
        # ---------- aba 🧪 Gaso: casos guiados ----------
        chk(pg.evaluate("!!document.querySelector('#nav a[data-v=gaso]')"), f"{T} link 🧪 Gaso na navegação")
        pg.evaluate("location.hash='#gaso'"); pg.wait_for_function("document.querySelector('#gzHost .gzHero')", timeout=15000)
        chk(pg.evaluate("$('#v-gaso').classList.contains('on')"), f"{T} rota #gaso abre a seção")
        chk("235 casos guiados" in pg.inner_text("#gzHost .gzHero"), f"{T} hero mostra 235 casos guiados")
        xp0 = pg.evaluate("xpTotal()")
        pg.click("#gzHost [data-gzgo=new]"); pg.wait_for_selector("#gzHost .gzCase")
        chk(pg.evaluate("!!$('#gzHost .gzCase table')"), f"{T} caso mostra o laudo (tabela)")
        steps = pg.evaluate("GZ.cur.steps.length"); chk(4 <= steps <= 6, f"{T} caso com 4–6 etapas ({steps})")
        for k in range(steps):
            c = pg.evaluate("GZ.cur.steps[GZ.si].c")
            pg.click(f"#gzHost [data-gzo='{c}']"); pg.wait_for_selector("#gzNext")
            if k == 0: chk(pg.evaluate("$('#gzHost .qzRes').classList.contains('ok') && !!$('#gzHost .gzExp')"), f"{T} etapa certa → ✅ + explicação")
            pg.click("#gzNext")
        pg.wait_for_selector("#gzHost .gzEnd")
        chk("Caso perfeito" in pg.inner_text("#gzHost .gzEnd"), f"{T} caso perfeito ⭐ ao acertar todas as etapas")
        et = pg.inner_text("#gzHost .gzEnd"); chk("Conduta" in et and "Pegadinha" in et, f"{T} final mostra diagnóstico, conduta e pegadinha")
        xp1 = pg.evaluate("xpTotal()"); chk(xp1 - xp0 >= 3 * steps + 10, f"{T} XP: +3/etapa +10 perfeito ({xp1 - xp0})")
        chk(pg.evaluate("Object.keys(S.logs._g||{}).length") == 1, f"{T} caso registrado em S.logs._g")
        chk(pg.evaluate("(S.logs[today()].xs||{}).g>0"), f"{T} XP contabilizado na fonte 🧪 Gasometria")
        chk(pg.evaluate("Object.values(S.logs[today()].hr||{}).reduce((a,b)=>a+b,0)") >= steps, f"{T} histograma de horário registra respostas")
        pg.click("#gzNextCase"); pg.wait_for_selector("#gzHost .gzCase")
        c = pg.evaluate("GZ.cur.steps[GZ.si].c"); wrong = (c + 1) % pg.evaluate("GZ.cur.steps[GZ.si].o.length")
        pg.click(f"#gzHost [data-gzo='{wrong}']"); pg.wait_for_selector("#gzNext")
        chk(pg.evaluate("$('#gzHost .qzRes').classList.contains('bad') && !!$('#gzHost .qzAlt.ok')"), f"{T} etapa errada → ❌ e mostra a correta")
        pg.keyboard.press("Enter"); pg.wait_for_timeout(150)
        chk(pg.evaluate("GZ.si") == 1, f"{T} atalho Enter avança a etapa")
        pg.keyboard.press(str(pg.evaluate("GZ.cur.steps[GZ.si].c") + 1)); pg.wait_for_timeout(150)
        chk(pg.evaluate("GZ.picked") is not None, f"{T} atalho numérico responde a etapa")
        w = pg.evaluate("document.documentElement.scrollWidth-document.documentElement.clientWidth"); chk(w <= 1, f"{T} caso sem estouro horizontal ({w}px)")
        pg.click("#gzQuit"); pg.wait_for_selector("#gzHost [data-gzgo=new]")
        # ---------- analisador ----------
        pg.click("#gzHost [data-gzsub=analisar]"); pg.wait_for_selector("#gzRun")
        chk(pg.evaluate("$$('#gzHost .gzForm input').length") == 16, f"{T} analisador com 16 campos")
        for k, v in [("ph", "7.21"), ("pco2", "28"), ("hco3", "11"), ("na", "140"), ("cl", "104"), ("alb", "4"), ("pao2", "80"), ("fio2", "21"), ("idade", "40")]:
            pg.fill(f"#gzf_{k}", v)
        pg.click("#gzRun"); pg.wait_for_selector("#gzOut .gzDx")
        dx = pg.inner_text("#gzOut .gzDx"); chk("Acidose metabólica" in dx and "AG" in dx.upper().replace("Â", "A") or "ânion" in dx.lower(), f"{T} analisador: acidose metabólica com AG elevado ({dx[:70]})")
        chk(pg.evaluate("$$('#gzOut .gzSteps li').length") >= 4, f"{T} analisador mostra o passo a passo")
        chk(pg.evaluate("!$('#gzOut .qzRes.bad')"), f"{T} laudo coerente sem alerta de Henderson-Hasselbalch")
        pg.fill("#gzf_ph", "7.50"); pg.click("#gzRun"); pg.wait_for_selector("#gzOut .gzDx")
        chk("incoerente" in pg.inner_text("#gzOut"), f"{T} alerta de laudo incoerente (pH × Henderson-Hasselbalch)")
        pg.click("#gzEx"); pg.wait_for_selector("#gzOut .gzDx"); chk(True, f"{T} 🎲 exemplo carrega e interpreta")
        w = pg.evaluate("document.documentElement.scrollWidth-document.documentElement.clientWidth"); chk(w <= 1, f"{T} analisador sem estouro ({w}px)")
        pg.click("#gzHost [data-gzsub=formulas]"); pg.wait_for_selector("#gzHost .gzF")
        chk(pg.evaluate("$$('#gzHost .gzF').length") == 16, f"{T} 16 fórmulas de bolso")
        # ---------- questões ----------
        pg.click("#gzHost [data-gzsub=casos]"); pg.wait_for_selector("#gzQz"); pg.click("#gzQz")
        pg.wait_for_function("location.hash==='#questoes' && document.querySelector('#qzHost [data-div=gaso].gold')", timeout=10000)
        chk(pg.evaluate("QZ.data.gaso.length") == 100, f"{T} 100 questões de gasometria")
        chk(pg.evaluate("$$('#qzHost [data-div]').length") == 3, f"{T} 3 divisões de questões (TEMI · R3 · Gasometria)")
        chk(pg.evaluate("new Set(QZ.data.gaso.map(q=>q.tema)).size") == 10, f"{T} questões cobrem os 10 temas")
        chk(pg.evaluate("QZ.data.gaso.every(q=>q.alts.length===5&&q.porque&&q.porque.length===5&&q.com&&q.pega&&q.gab>=0&&q.gab<5)"), f"{T} todas com 5 alternativas, comentário, porquê e pegadinha")
        pg.click("#qzHost [data-st='10']"); pg.wait_for_selector("#qzHost .qzAlt")
        pg.keyboard.press("A"); pg.wait_for_selector("#qzHost .qzRes")
        chk(True, f"{T} questão de gasometria respondida")
        w = pg.evaluate("document.documentElement.scrollWidth-document.documentElement.clientWidth"); chk(w <= 1, f"{T} questão sem estouro ({w}px)")
        pg.click("#qzQuit"); pg.wait_for_timeout(300)
        chk("Gasometria" in pg.evaluate("JSON.stringify(dayLogs().flatMap(([,l])=>l.sims||[]))"), f"{T} bloco registrado como 'Questões Gasometria'")
        chk(pg.evaluate("DOM.rows().some(r=>r.div==='gaso')") if pg.evaluate("typeof DOM.rows==='function'") else True, f"{T} mapa de domínio inclui gasometria")
        # ---------- Jornada ----------
        pg.evaluate("location.hash='#jornada'"); pg.wait_for_selector("#jrHost .jrChips")
        nA = pg.evaluate("ACH.list.length"); chk(nA >= 180, f"{T} conquistas ampliadas ({nA})")
        chk(pg.evaluate("new Set(ACH.list.map(a=>a.id)).size===ACH.list.length"), f"{T} ids de conquista únicos")
        chk(pg.evaluate(f"{OLD!r}.every(id=>ACH.list.some(a=>a.id===id))"), f"{T} ids antigos preservados (conquistas já ganhas continuam)")
        gr = pg.evaluate("Object.fromEntries(Object.keys(ACH_G).map(k=>[k,ACH.list.filter(a=>a.grp===k).length]))")
        chk(all(gr[k] >= 8 for k in ["ass", "cat", "des", "est", "tit", "hon"]), f"{T} grupos com conteúdo {gr}")
        chk(pg.evaluate("ACH.list.every(a=>a.grp && ACH_T[a.tipo] && ACH_BONUS[a.tipo])"), f"{T} toda conquista tem grupo e tipo válidos")
        chk(pg.evaluate("ACH.list.filter(a=>a.id.startsWith('cat_gaso')).length") == 4, f"{T} trilha 🧪 Alquimista Ácido-Base (4 níveis)")
        chk(pg.evaluate("$$('#jrHost .jrChips button').length") == 8, f"{T} 8 filtros do salão de troféus")
        chk(pg.evaluate("!!$('#jrHost .styleChips') && $$('#jrHost .styleChips span').length===5"), f"{T} painel 🎭 estilo de estudo (5 traços)")
        chk("Alquimista" in pg.inner_text("#jrHost .catGrid"), f"{T} domínio por categoria inclui 🧪 Gasometria")
        for k in ["ass", "cat", "des", "est", "tit", "hon", "all", "prox"]:
            pg.click(f"#jrHost [data-jrg={k}]"); pg.wait_for_selector(f"#jrHost [data-jrg={k}].gold")
        chk(pg.evaluate("$$('#jrHost .achGrid .ach').length") >= 12, f"{T} filtros alternam e ⭐ Próximas lista as mais perto")
        got = pg.evaluate("Object.keys(S.logs._a||{})"); chk("gz5" not in got, f"{T} sem conquista indevida de gasometria")
        pg.evaluate("S.logs._a=Object.assign(S.logs._a||{}, {xp500:Date.now()-5000, gzq80:Date.now()}); JR.render()"); pg.wait_for_selector("#jrTit")
        pg.select_option("#jrTit", "xp500"); pg.wait_for_timeout(300)
        chk(pg.evaluate("S.logs._tt && S.logs._tt.id==='xp500'") and "Iniciado do Códice" in pg.inner_text("#jrHost .jrTitle"), f"{T} 🏷️ título ativo escolhido e exibido")
        mg = pg.evaluate("mergeLogs({_tt:{id:'a',t:1}},{_tt:{id:'b',t:2}})._tt.id+mergeLogs({_tt:{id:'a',t:3}},{_tt:{id:'b',t:2}})._tt.id")
        chk(mg == "ba", f"{T} sincronização do título: vence a escolha mais recente ({mg})")
        st = pg.evaluate("(()=>{const s=jStats();return [s.dias,s.gN,s.gP,s.gA,s.gqA,typeof s.cat.gaso]})()")
        chk(st[0] >= 1 and st[1] >= 1 and st[2] >= 1 and st[3] >= 1 and st[4] >= 1 and st[5] == "object", f"{T} jStats: dias {st[0]} · casos {st[1]} · perfeitos {st[2]} · análises {st[3]} · questões {st[4]}")
        w = pg.evaluate("document.documentElement.scrollWidth-document.documentElement.clientWidth"); chk(w <= 1, f"{T} Jornada sem estouro ({w}px)")
        pg.evaluate("document.documentElement.classList.add('light')"); pg.evaluate("location.hash='#gaso'"); pg.wait_for_selector("#gzHost .gzHero")
        bg = pg.evaluate("getComputedStyle($('#gzHost .gzHero')).backgroundImage")
        chk("gradient" in bg, f"{T} tema claro aplica regras à aba 🧪")
        idx = pg.evaluate("fetch('data/index.json').then(r=>r.json()).then(j=>[j.colecoes.find(c=>c.id==='gaso'), j.pacotes.find(p=>p.nome==='pack-7-gaso')])")
        chk(idx[0] and idx[0]["cards"] == 300 and idx[1] and idx[1]["cards"] == 300, f"{T} índice: coleção 🧪 e pack-7 com 300 cards")
        chk(not errs, f"{T} sem erro de JS {errs[:2]}")
        ctx.close()
    br.close()
print(f"\n{len(ok)} ok · {len(bad)} falhas"); sys.exit(1 if bad else 0)
